3|/// <summary>
4|/// Represents a multi selection list prompt.
5|/// </summary>
6|/// <typeparam name="T">The prompt result type.</typeparam>
7|public sealed class MultiSelectionPrompt<T> : IPrompt<List<T>>, IListPromptStrategy<T>
8|    where T : notnull
9|{
10|    /// <summary>
11|    /// Gets or sets the title.
12|    /// </summary>
13|    public string? Title { get; set; }
14|
15|    /// <summary>
16|    /// Gets or sets the page size.
17|    /// Defaults to <c>10</c>.
18|    /// </summary>
19|    public int PageSize { get; set; } = 10;
20|
21|    /// <summary>
22|    /// Gets or sets a value indicating whether the selection should wrap around when reaching the edge.
23|    /// Defaults to <c>false</c>.
24|    /// </summary>
25|    public bool WrapAround { get; set; } = false;
26|
27|    /// <summary>
28|    /// Gets or sets the highlight style of the selected choice.
29|    /// </summary>
30|    public Style? HighlightStyle { get; set; }
31|
32|    /// <summary>
33|    /// Gets or sets the converter to get the display string for a choice. By default
34|    /// the corresponding <see cref="TypeConverter"/> is used.
35|    /// </summary>
36|    public Func<T, string>? Converter { get; set; }
37|
38|    /// <summary>
39|    /// Gets or sets a value indicating whether or not
40|    /// at least one selection is required.
41|    /// </summary>
42|    public bool Required { get; set; } = true;
43|
44|    /// <summary>
45|    /// Gets or sets the text that will be displayed if there are more choices to show.
46|    /// </summary>
47|    public string? MoreChoicesText { get; set; }
48|
49|    /// <summary>
50|    /// Gets or sets the text that instructs the user of how to select items.
51|    /// </summary>
52|    public string? InstructionsText { get; set; }
53|
54|    /// <summary>
55|    /// Gets or sets the selection mode.
56|    /// Defaults to <see cref="SelectionMode.Leaf"/>.
57|    /// </summary>
58|    public SelectionMode Mode { get; set; } = SelectionMode.Leaf;
59|
60|    internal ListPromptTree<T> Tree { get; }
61|
62|    /// <summary>
63|    /// Initializes a new instance of the <see cref="MultiSelectionPrompt{T}"/> class.
64|    /// </summary>
65|    /// <param name="comparer">
66|    /// The <see cref="IEqualityComparer{T}"/> implementation to use when comparing items,
67|    /// or <c>null</c> to use the default <see cref="IEqualityComparer{T}"/> for the type of the item.
68|    /// </param>
69|    public MultiSelectionPrompt(IEqualityComparer<T>? comparer = null)
70|    {
71|        Tree = new ListPromptTree<T>(comparer ?? EqualityComparer<T>.Default);
72|    }
73|
74|    /// <summary>
75|    /// Adds a choice.
76|    /// </summary>
77|    /// <param name="item">The item to add.</param>
78|    /// <returns>A <see cref="IMultiSelectionItem{T}"/> so that multiple calls can be chained.</returns>
79|    public IMultiSelectionItem<T> AddChoice(T item)
80|    {
81|        var node = new ListPromptItem<T>(item);
82|        Tree.Add(node);
83|        return node;
84|    }
85|
86|    /// <inheritdoc/>
87|    public List<T> Show(IAnsiConsole console)
88|    {
89|        return ShowAsync(console, CancellationToken.None).GetAwaiter().GetResult();
90|    }
91|
92|    /// <inheritdoc/>
93|    public async Task<List<T>> ShowAsync(IAnsiConsole console, CancellationToken cancellationToken)
94|    {
95|        // Create the list prompt
96|        var prompt = new ListPrompt<T>(console, this);
97|        var result = await prompt.Show(Tree, cancellationToken, PageSize, WrapAround).ConfigureAwait(false);
98|
99|        if (Mode == SelectionMode.Leaf)
100|        {
101|            return result.Items
102|                .Where(x => x.IsSelected && x.Children.Count == 0)
103|                .Select(x => x.Data)
104|                .ToList();
105|        }
106|
107|        return result.Items
108|            .Where(x => x.IsSelected)
109|            .Select(x => x.Data)
110|            .ToList();
111|    }
112|
113|    /// <summary>
114|    /// Returns all parent items of the given <paramref name="item"/>.
115|    /// </summary>
116|    /// <param name="item">The item for which to find the parents.</param>
117|    /// <returns>The parent items, or an empty list, if the given item has no parents.</returns>
118|    public IEnumerable<T> GetParents(T item)
119|    {
120|        var promptItem = Tree.Find(item);
121|        if (promptItem == null)
122|        {
123|            throw new ArgumentOutOfRangeException(nameof(item), "Item not found in tree.");
124|        }
125|
126|        var parents = new List<ListPromptItem<T>>();
127|        while (promptItem.Parent != null)
128|        {
129|            promptItem = promptItem.Parent;
130|            parents.Add(promptItem);
131|        }
132|
133|        return parents
134|            .ReverseEnumerable()
135|            .Select(x => x.Data);
136|    }
137|
138|    /// <summary>
139|    /// Returns the parent item of the given <paramref name="item"/>.
140|    /// </summary>
141|    /// <param name="item">The item for which to find the parent.</param>
142|    /// <returns>The parent item, or <c>null</c> if the given item has no parent.</returns>
143|    public T? GetParent(T item)
144|    {
145|        return GetParents(item).LastOrDefault();
146|    }
147|
148|    /// <inheritdoc/>
149|    ListPromptInputResult IListPromptStrategy<T>.HandleInput(ConsoleKeyInfo key, ListPromptState<T> state)
150|    {
151|        if (key.Key == ConsoleKey.Enter)
152|        {
153|            if (Required && state.Items.None(x => x.IsSelected))
154|            {
155|                // Selection not permitted
156|                return ListPromptInputResult.None;
157|            }
158|
159|            // Submit
160|            return ListPromptInputResult.Submit;
161|        }
162|
163|        if (key.Key == ConsoleKey.Spacebar)
164|        {
165|            var current = state.Items[state.Index];
166|            var select = !current.IsSelected;
167|
168|            if (Mode == SelectionMode.Leaf)
169|            {
170|                // Select the node and all its children
171|                foreach (var item in current.Traverse(includeSelf: true))
172|                {
173|                    item.IsSelected = select;
174|                }
175|
176|                // Visit every parent and evaluate if its selection
177|                // status need to be updated
178|                var parent = current.Parent;
179|                while (parent != null)
180|                {
181|                    parent.IsSelected = parent.Traverse(includeSelf: false).All(x => x.IsSelected);
182|                    parent = parent.Parent;
183|                }
184|            }
185|            else
186|            {
187|                current.IsSelected = !current.IsSelected;
188|            }
189|
190|            // Refresh the list
191|            return ListPromptInputResult.Refresh;
192|        }
193|
194|        return ListPromptInputResult.None;
195|    }
196|
197|    /// <inheritdoc/>
198|    int IListPromptStrategy<T>.CalculatePageSize(IAnsiConsole console, int totalItemCount, int requestedPageSize)
199|    {
200|        // The instructions take up two rows including a blank line
201|        var extra = 2;
202|        if (Title != null)
203|        {
204|            // Title takes up two rows including a blank line
205|            extra += 2;
206|        }
207|
208|        // Scrolling?
209|        if (totalItemCount > requestedPageSize)
210|        {
211|            // The scrolling instructions takes up one row
212|            extra++;
213|        }
214|
215|        var pageSize = requestedPageSize;
216|        if (pageSize > console.Profile.Height - extra)
217|        {
218|            pageSize = console.Profile.Height - extra;
219|        }
220|
221|        return pageSize;
222|    }
223|
224|    /// <inheritdoc/>
225|    IRenderable IListPromptStrategy<T>.Render(IAnsiConsole console, bool scrollable, int cursorIndex, IEnumerable<(int Index, ListPromptItem<T> Node)> items)
226|    {
227|        var list = new List<IRenderable>();
228|        var highlightStyle = HighlightStyle ?? new Style(foreground: Color.Blue);
229|
230|        if (Title != null)
231|        {
232|            list.Add(new Markup(Title));
233|        }
234|
235|        var grid = new Grid();
236|        grid.AddColumn(new GridColumn().Padding(0, 0, 1, 0).NoWrap());
237|
238|        if (Title != null)
239|        {
240|            grid.AddEmptyRow();
241|        }
242|
243|        foreach (var item in items)
244|        {
245|            var current = item.Index == cursorIndex;
246|            var style = current ? highlightStyle : Style.Plain;
247|
248|            var indent = new string(' ', item.Node.Depth * 2);
249|            var prompt = item.Index == cursorIndex ? ListPromptConstants.Arrow : new string(' ', ListPromptConstants.Arrow.Length);
250|
251|            var text = (Converter ?? TypeConverterHelper.ConvertToString)?.Invoke(item.Node.Data) ?? item.Node.Data.ToString() ?? "?";
252|            if (current)
253|            {
254|                text = text.RemoveMarkup().EscapeMarkup();
255|            }
256|
257|            var checkbox = item.Node.IsSelected
258|                ? (item.Node.IsGroup && Mode == SelectionMode.Leaf
259|                    ? ListPromptConstants.GroupSelectedCheckbox : ListPromptConstants.SelectedCheckbox)
260|                : ListPromptConstants.Checkbox;
261|
262|            grid.AddRow(new Markup(indent + prompt + " " + checkbox + " " + text, style));
263|        }
264|
265|        list.Add(grid);
266|        list.Add(Text.Empty);
267|
268|        if (scrollable)
269|        {
270|            // There are more choices
271|            list.Add(new Markup(MoreChoicesText ?? ListPromptConstants.MoreChoicesMarkup));
272|        }
273|
274|        // Instructions
275|        list.Add(new Markup(InstructionsText ?? ListPromptConstants.InstructionsMarkup));
276|
277|        // Combine all items
278|        return new Rows(list);
279|    }
