1|namespace Spectre.Console;
2|
3|internal sealed class ListPromptState<T>
4|    where T : notnull
5|{
6|    public int Index { get; private set; }
7|    public int ItemCount => Items.Count;
8|    public int PageSize { get; }
9|    public bool WrapAround { get; }
10|    public IReadOnlyList<ListPromptItem<T>> Items { get; }
11|
12|    public ListPromptItem<T> Current => Items[Index];
13|
14|    public ListPromptState(IReadOnlyList<ListPromptItem<T>> items, int pageSize, bool wrapAround)
15|    {
16|        Index = 0;
17|        Items = items;
18|        PageSize = pageSize;
19|        WrapAround = wrapAround;
20|    }
21|
22|    public bool Update(ConsoleKey key)
23|    {
24|        var index = key switch
25|        {
26|            ConsoleKey.UpArrow => Index - 1,
27|            ConsoleKey.DownArrow => Index + 1,
28|            ConsoleKey.Home => 0,
29|            ConsoleKey.End => ItemCount - 1,
30|            ConsoleKey.PageUp => Index - PageSize,
31|            ConsoleKey.PageDown => Index + PageSize,
32|            _ => Index,
33|        };
34|
35|        index = WrapAround
36|            ? (ItemCount + (index % ItemCount)) % ItemCount
37|            : index.Clamp(0, ItemCount - 1);
38|        if (index != Index)
39|        {
40|            Index = index;
41|            return true;
42|        }
43|
44|        return false;
45|    }
