1|namespace Spectre.Console;
2|
3|internal sealed class ListPrompt<T>
4|    where T : notnull
5|{
6|    private readonly IAnsiConsole _console;
7|    private readonly IListPromptStrategy<T> _strategy;
8|
9|    public ListPrompt(IAnsiConsole console, IListPromptStrategy<T> strategy)
10|    {
11|        _console = console ?? throw new ArgumentNullException(nameof(console));
12|        _strategy = strategy ?? throw new ArgumentNullException(nameof(strategy));
13|    }
14|
15|    public async Task<ListPromptState<T>> Show(
16|        ListPromptTree<T> tree,
17|        CancellationToken cancellationToken,
18|        int requestedPageSize = 15,
19|        bool wrapAround = false)
20|    {
21|        if (tree is null)
22|        {
23|            throw new ArgumentNullException(nameof(tree));
24|        }
25|
26|        if (!_console.Profile.Capabilities.Interactive)
27|        {
28|            throw new NotSupportedException(
29|                "Cannot show selection prompt since the current " +
30|                "terminal isn't interactive.");
31|        }
32|
33|        if (!_console.Profile.Capabilities.Ansi)
34|        {
35|            throw new NotSupportedException(
36|                "Cannot show selection prompt since the current " +
37|                "terminal does not support ANSI escape sequences.");
38|        }
39|
40|        var nodes = tree.Traverse().ToList();
41|        var state = new ListPromptState<T>(nodes, _strategy.CalculatePageSize(_console, nodes.Count, requestedPageSize), wrapAround);
42|        var hook = new ListPromptRenderHook<T>(_console, () => BuildRenderable(state));
43|
44|        using (new RenderHookScope(_console, hook))
45|        {
46|            _console.Cursor.Hide();
47|            hook.Refresh();
48|
49|            while (true)
50|            {
51|                var rawKey = await _console.Input.ReadKeyAsync(true, cancellationToken).ConfigureAwait(false);
52|                if (rawKey == null)
53|                {
54|                    continue;
55|                }
56|
57|                var key = rawKey.Value;
58|                var result = _strategy.HandleInput(key, state);
59|                if (result == ListPromptInputResult.Submit)
60|                {
61|                    break;
62|                }
63|
64|                if (state.Update(key.Key) || result == ListPromptInputResult.Refresh)
65|                {
66|                    hook.Refresh();
67|                }
68|            }
69|        }
70|
71|        hook.Clear();
72|        _console.Cursor.Show();
73|
74|        return state;
75|    }
76|
77|    private IRenderable BuildRenderable(ListPromptState<T> state)
78|    {
79|        var pageSize = state.PageSize;
80|        var middleOfList = pageSize / 2;
81|
82|        var skip = 0;
83|        var take = state.ItemCount;
84|        var cursorIndex = state.Index;
85|
86|        var scrollable = state.ItemCount > pageSize;
87|        if (scrollable)
88|        {
89|            skip = Math.Max(0, state.Index - middleOfList);
90|            take = Math.Min(pageSize, state.ItemCount - skip);
91|
92|            if (state.ItemCount - state.Index < middleOfList)
93|            {
94|                // Pointer should be below the end of the list
95|                var diff = middleOfList - (state.ItemCount - state.Index);
96|                skip -= diff;
97|                take += diff;
98|                cursorIndex = middleOfList + diff;
99|            }
100|            else
101|            {
102|                // Take skip into account
103|                cursorIndex -= skip;
104|            }
105|        }
106|
107|        // Build the renderable
108|        return _strategy.Render(
109|            _console,
110|            scrollable, cursorIndex,
111|            state.Items.Skip(skip).Take(take)
112|                .Select((node, index) => (index, node)));
113|    }
