3|/// <summary>
4|/// Contains extension methods for <see cref="IAnsiConsole"/>.
5|/// </summary>
6|public static partial class AnsiConsoleExtensions
7|{
8|    internal static async Task<string> ReadLine(this IAnsiConsole console, Style? style, bool secret, char? mask, IEnumerable<string>? items = null, CancellationToken cancellationToken = default)
9|    {
10|        if (console is null)
11|        {
12|            throw new ArgumentNullException(nameof(console));
13|        }
14|
15|        style ??= Style.Plain;
16|        var text = string.Empty;
17|
18|        var autocomplete = new List<string>(items ?? Enumerable.Empty<string>());
19|
20|        while (true)
21|        {
22|            var rawKey = await console.Input.ReadKeyAsync(true, cancellationToken).ConfigureAwait(false);
23|            if (rawKey == null)
24|            {
25|                continue;
26|            }
27|
28|            var key = rawKey.Value;
29|            if (key.Key == ConsoleKey.Enter)
30|            {
31|                return text;
32|            }
33|
34|            if (key.Key == ConsoleKey.Tab && autocomplete.Count > 0)
35|            {
36|                var autoCompleteDirection = key.Modifiers.HasFlag(ConsoleModifiers.Shift)
37|                    ? AutoCompleteDirection.Backward
38|                    : AutoCompleteDirection.Forward;
39|                var replace = AutoComplete(autocomplete, text, autoCompleteDirection);
40|                if (!string.IsNullOrEmpty(replace))
41|                {
42|                    // Render the suggestion
43|                    console.Write("\b \b".Repeat(text.Length), style);
44|                    console.Write(replace);
45|                    text = replace;
46|                    continue;
47|                }
48|            }
49|
50|            if (key.Key == ConsoleKey.Backspace)
51|            {
52|                if (text.Length > 0)
53|                {
54|                    text = text.Substring(0, text.Length - 1);
55|                    console.Write("\b \b");
56|                }
57|
58|                continue;
59|            }
60|
61|            if (!char.IsControl(key.KeyChar))
62|            {
63|                text += key.KeyChar.ToString();
64|                var output = key.KeyChar.ToString();
65|                console.Write(secret ? output.Mask(mask) : output, style);
66|            }
67|        }
68|    }
69|
70|    private static string AutoComplete(List<string> autocomplete, string text, AutoCompleteDirection autoCompleteDirection)
71|    {
72|        var found = autocomplete.Find(i => i == text);
73|        var replace = string.Empty;
74|
75|        if (found == null)
76|        {
77|            // Get the closest match
78|            var next = autocomplete.Find(i => i.StartsWith(text, true, CultureInfo.InvariantCulture));
79|            if (next != null)
80|            {
81|                replace = next;
82|            }
83|            else if (string.IsNullOrEmpty(text))
84|            {
85|                // Use the first item
86|                replace = autocomplete[0];
87|            }
88|        }
89|        else
90|        {
91|            // Get the next match
92|            replace = GetAutocompleteValue(autoCompleteDirection, autocomplete, found);
93|        }
94|
95|        return replace;
96|    }
97|
98|    private static string GetAutocompleteValue(AutoCompleteDirection autoCompleteDirection, IList<string> autocomplete, string found)
99|    {
100|        var foundAutocompleteIndex = autocomplete.IndexOf(found);
101|        var index = autoCompleteDirection switch
102|        {
103|            AutoCompleteDirection.Forward => foundAutocompleteIndex + 1,
104|            AutoCompleteDirection.Backward => foundAutocompleteIndex - 1,
105|            _ => throw new ArgumentOutOfRangeException(nameof(autoCompleteDirection), autoCompleteDirection, null),
106|        };
107|
108|        if (index >= autocomplete.Count)
109|        {
110|            index = 0;
111|        }
112|
113|        if (index < 0)
114|        {
115|            index = autocomplete.Count - 1;
116|        }
117|
118|        return autocomplete[index];
119|    }
120|
121|    private enum AutoCompleteDirection
122|    {
123|        Forward,
124|        Backward,
125|    }
