6|public sealed class TestConsole : IAnsiConsole, IDisposable
7|{
8|    private readonly IAnsiConsole _console;
9|    private readonly StringWriter _writer;
10|    private IAnsiConsoleCursor? _cursor;
11|
12|    /// <inheritdoc/>
13|    public Profile Profile => _console.Profile;
14|
15|    /// <inheritdoc/>
16|    public IExclusivityMode ExclusivityMode => _console.ExclusivityMode;
17|
18|    /// <summary>
19|    /// Gets the console input.
20|    /// </summary>
21|    public TestConsoleInput Input { get; }
22|
23|    /// <inheritdoc/>
24|    public RenderPipeline Pipeline => _console.Pipeline;
25|
26|    /// <inheritdoc/>
27|    public IAnsiConsoleCursor Cursor => _cursor ?? _console.Cursor;
28|
29|    /// <inheritdoc/>
30|    IAnsiConsoleInput IAnsiConsole.Input => Input;
31|
32|    /// <summary>
33|    /// Gets the console output.
34|    /// </summary>
35|    public string Output => _writer.ToString();
36|
37|    /// <summary>
38|    /// Gets the console output lines.
39|    /// </summary>
40|    public IReadOnlyList<string> Lines => Output.NormalizeLineEndings().TrimEnd('\n').Split(new char[] { '\n' });
41|
42|    /// <summary>
43|    /// Gets or sets a value indicating whether or not VT/ANSI sequences
44|    /// should be emitted to the console.
45|    /// </summary>
46|    public bool EmitAnsiSequences { get; set; }
47|
48|    /// <summary>
49|    /// Initializes a new instance of the <see cref="TestConsole"/> class.
50|    /// </summary>
51|    public TestConsole()
52|    {
53|        _writer = new StringWriter();
54|        _cursor = new NoopCursor();
55|
56|        Input = new TestConsoleInput();
57|        EmitAnsiSequences = false;
58|
59|        _console = AnsiConsole.Create(new AnsiConsoleSettings
60|        {
61|            Ansi = AnsiSupport.Yes,
62|            ColorSystem = (ColorSystemSupport)ColorSystem.TrueColor,
63|            Out = new AnsiConsoleOutput(_writer),
64|            Interactive = InteractionSupport.No,
65|            ExclusivityMode = new NoopExclusivityMode(),
66|            Enrichment = new ProfileEnrichment
67|            {
68|                UseDefaultEnrichers = false,
69|            },
70|        });
71|
72|        _console.Profile.Width = 80;
73|        _console.Profile.Height = 24;
74|        _console.Profile.Capabilities.Ansi = true;
75|        _console.Profile.Capabilities.Unicode = true;
76|    }
77|
78|    /// <inheritdoc/>
79|    public void Dispose()
80|    {
81|        _writer.Dispose();
82|    }
83|
84|    /// <inheritdoc/>
85|    public void Clear(bool home)
86|    {
87|        _console.Clear(home);
88|    }
89|
90|    /// <inheritdoc/>
91|    public void Write(IRenderable renderable)
92|    {
93|        if (EmitAnsiSequences)
94|        {
95|            _console.Write(renderable);
96|        }
97|        else
98|        {
99|            foreach (var segment in renderable.GetSegments(this))
100|            {
101|                if (segment.IsControlCode)
102|                {
103|                    continue;
104|                }
105|
106|                Profile.Out.Writer.Write(segment.Text);
107|            }
108|        }
109|    }
110|
